import { describe, test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { functionEnvironment } from '../lib/deploy/stack.js';
import { start } from '../src/server.js';
import { sign } from '../src/hooks/signing.js';

// The three places the app runs in production (lib/deploy/README.md). For each one: the environment
// the definition hands to `node src/main.js`, before the deploy fills in the references.
const yamlEnvironment = (file) => {
  const text = readFileSync(new URL(`../lib/deploy/${file}`, import.meta.url), 'utf8');
  return Object.fromEntries([...text.matchAll(/^\s+([A-Z][A-Z0-9_]*):\s*(\S.*)$/gm)].map((m) => [m[1], m[2]]));
};

const definitions = [
  {
    name: 'cloud function (stack.js)',
    environment: functionEnvironment,
    // param('<path>'): read from the parameter store at deploy time.
    isReference: (v) => typeof v === 'object' && v !== null && /^\/booking-hooks\/prod\/[a-z0-9-]+$/.test(v.fromParameter),
    fill: (v, lookup) => (typeof v === 'string' ? v : lookup(v.fromParameter) ?? ''),
  },
  {
    name: 'retry worker (cloud.yml)',
    environment: () => yamlEnvironment('cloud.yml'),
    // ${secret:<name>}: replaced by the deploy tool with the value from the secret store.
    isReference: (v) => /^\$\{secret:booking-hooks-[a-z0-9-]+\}$/.test(v),
    fill: (v, lookup) => v.replace(/\$\{secret:([^}]+)\}/g, (_, name) => lookup(name) ?? ''),
  },
  {
    name: 'office box (box-compose.yml)',
    environment: () => yamlEnvironment('box-compose.yml'),
    // ${<NAME>}: comes from the host's env file.
    isReference: (v) => /^\$\{[A-Z][A-Z0-9_]*\}$/.test(v),
    fill: (v, lookup) => v.replace(/\$\{([^}]+)\}/g, (_, name) => lookup(name) ?? ''),
  },
];

// What the app sees at start-up once the deploy has filled in every reference.
const filled = (d, lookup) =>
  Object.fromEntries(Object.entries(d.environment()).map(([name, v]) => [name, d.fill(v, lookup)]));

for (const d of definitions) {
  describe(`deploy definition: ${d.name}`, () => {
    test('with the values registered, production starts and takes a signed booking', () => {
      const env = filled(d, (reference) => `registered:${reference}`);
      assert.equal(env.NODE_ENV, 'production');
      const app = start(env);
      const body = '{"room":"A-3","date":"2026-12-01"}';
      assert.equal(app.receive(body, sign(body, env.HOOK_SIGNING_KEY)).status, 202);
    });

    test('the signing key is passed as a reference, never as a value', () => {
      const raw = d.environment().HOOK_SIGNING_KEY;
      assert.ok(d.isReference(raw), `HOOK_SIGNING_KEY must be a reference in this definition, got: ${JSON.stringify(raw)}`);
    });

    test('while the signing key is not registered, production still does not start', () => {
      const env = filled(d, (reference) => (/signing/i.test(reference) ? undefined : `registered:${reference}`));
      assert.throws(() => start(env), /HOOK_SIGNING_KEY is required/);
    });
  });
}

